\u0072\u0073\u0075\u0046\u0068\u005f\u005a\u0057\u0079\u006b\u004d\u0032\u004d\u0079\u0034\u0026\u0031\u0042\u0051\u0068\u0071\u004d\u0062\u0067\u002b\u006c\u0060\u0032\u0070\u0047\u0065\u005d\u004e\u007a\u006c\u0031\u0061\u006f\u0046\u0054\u003a\u0040\u003b\u007a\u0040\u0063\u0052\u004b\u0042\u0025\u0021\u0031\u0024\u0059\u0042\u0058\u006d\u005a\u0055\u0024\u004a\u0075\u004f\u0025\u006c\u002b\u003c\u005a\u004e\u003f\u0075\u0058\u0032\u0026\u005e\u0074\u0067\u006d\u004f\u007d\u003c\u0040\u0023\u005a\u004e\u003f\u0075\u0051\u007d\u003b\u0073\u0055\u005b\u006c\u006f\u005e\u0028\u0064\u006f\u0054\u007b\u0058\u005f\u0063\u0032\u007e\u002e\u0066\u0038\u0079\u005e\u005d\u0061\u0030\u003c\u0074\u005a\u0044\u0031\u0073\u0035\u0060\u0033\u0038\u0066\u0031\u005e\u002e\u0061\u0065\u0050\u0066\u004d\u002b\u0039\u006c\u0022\u0060\u0033\u004d\u002f\u0059\u0023\u0055\u0061\u0078\u0068\u0057\u0042\u0039\u0075\u0021\u0026\u0071\u0049\u007d\u006f\u0038\u004d\u0023\u007a\u0063\u0024\u0026\u003d\u0059\u0026\u007d\u004b\u0072\u007b\u0049\u004a\u0071\u0066\u003f\u006e\u0061\u0049\u0076\u0064\u0063\u0029\u0038\u0041\u0079\u0034\u0033\u0043\u0046\u0058\u004f\u006f\u0058\u0052\u006f\u0032\u004c\u007c\u003f\u007b\u003c\u0024\u0054\u0046\u0062\u004a\u004e\u004f\u0039\u0077\u0024\u0023\u0072\u0068\u0063\u0043\u0025\u002a\u0069\u004e\u0078\u0033\u005d\u0025\u0039\u0030\u0072\u0066\u0042\u0025\u003f\u004c\u004f\u0077\u0059\u0055\u002c\u003a\u004e\u007d\u0023\u0047\u007e\u004b\u0052\u006c\u003b\u0031\u004f\u0065\u0068\u006a\u0059\u003c\u002a\u0038\u0041\u0068\u0052\u0026\u0055\u005b\u0022\u0039\u0041\u003d\u0060\u005e\u005e\u002e\u0040\u0041\u005b\u0042\u0065\u007b\u007c\u0067\u0072\u0050\u0073\u0060\u0023\u006f\u0074\u0066\u0045\u004c\u003a\u0068\u005d\u0036\u0039\u0064\u0066\u0063\u002f\u0073\u005f\u0026\u005f\u007b\u005a\u006d\u0053\u0024\u0047\u0043\u0030\u0037\u0066\u002b\u0051\u0029\u0065\u0055\u002e\u0061\u004e\u0079\u0038\u0063\u004f\u0026\u0041\u0049\u0034\u007d\u0029\u004d\u0049\u003c\u004c\u0055\u0076\u0067\u003d\u006b\u0049\u005f\u004f\u007d\u007a\u004d\u0028\u003a\u003f\u0024\u0054\u0023\u006c\u0076\u005f\u006f\u006f\u002f\u0054\u0034\u0056\u005f\u0078\u0040\u005d\u0069\u002b\u0021\u0035\u0034\u0062\u0040\u0039\u0030\u003c\u005d\u0070\u0070\u005a\u0065\u0065\u0062\u0046\u007a\u006f\u0074\u0054\u003f\u0073\u0040\u006e\u005a\u004a\u0043\u0037\u003d\u0071\u0069\u0061\u0079\u003a\u0035\u0033\u0072\u005e\u005d\u007d\u0058\u0051\u003b\u002c\u0040\u0043\u0052\u0062\u007c\u0057\u003f\u0037\u004f\u0075\u0060\u0053\u0070\u0062\u0055\u002f\u0057\u007b\u0074\u0052\u0034\u003a\u005e\u0026\u006f\u0072\u004b\u0062\u0052\u007d\u0058\u005e\u004e\u0030\u0079\u003b\u0021\u0042\u0055\u006c\u0031\u0076\u003e\u006f\u0054\u0068\u0032\u0038\u0041\u0039\u0072\u0057\u0058\u0077\u0077\u002f\u0048\u002b\u0045\u005b\u007d\u0035\u0051\u005b\u0056\u0066\u003c\u0057\u0042\u0061\u005f\u004a\u0075\u007e\u0075\u0056\u0076\u0073\u0078\u0024\u006f\u007d\u0078\u003b\u0047\u004b\u0060\u0047\u0078\u003a\u004a\u0052\u002f\u005e\u0069\u0079\u0037\u006e\u0070\u0045\u006a\u0043\u0033\u0065\u0022\u003f\u0041\u0075\u006d\u0070\u0052\u0029\u004d\u0058\u0068\u0066\u0071\u007e\u0065\u0040\u002c\u0023\u006c\u0077\u002a\u0071\u0063\u006d\u002b\u0068\u002a\u0037\u005f\u0040\u0052\u002f\u0063\u005a\u0064\u005e\u006b\u0063\u004a\u005f\u004c\u0053\u0032\u006a\u007c\u0036\u0069\u006d\u0055\u002c\u006f\u0064\u004e\u0053\u0065\u002b\u0038\u0043\u0069\u0025\u006b\u003b\u0068\u0022\u003f\u0048\u0072\u0042\u005b\u0032\u0030\u006e\u0056\u0079\u0066\u0057\u006e\u0073\u0077\u004d\u005d\u005f\u0034\u0032\u005b\u0063\u0063\u006e\u0056\u0070\u0045\u0044\u0075\u0056\u007b\u0079\u0078\u0023\u0073\u0067\u0075\u0056\u0041\u0067\u004b\u002a\u006a\u0046\u004d\u0076\u0052\u0056\u0046\u0032\u0046\u003b\u0075\u0043\u0072\u0040\u0035\u0068\u005e\u005d\u002b\u004c\u0068\u006d\u0077\u0071\u0074\u0079\u0063\u003c\u007e\u0065\u007d\u003d\u0069\u0033\u006b\u0037\u0054\u007c\u003d\u0058\u0032\u0062\u002a\u0064\u003c\u0069\u0062\u004c\u0045\u004b\u007e\u0061\u002f\u003d\u004a\u0024\u0072\u0032\u0025\u002e\u0067\u0026\u007d\u0060\u0071\u0055\u006e\u004c\u0068\u006d\u0077\u0056\u0077\u0039\u0021\u0050\u0029\u007c\u0074\u0060\u0071\u002b\u006e\u005e\u002f\u0049\u004f\u004b\u0061\u003d\u0047\u0050\u0029\u005b\u003d\u0038\u0071\u0062\u005d\u0050\u002f\u003d\u004a\u005d\u005e\u005f\u002a\u0050\u0048\u0028\u0058\u0070\u0045\u006a\u0030\u002a\u004b\u0064\u0078\u0033\u0037\u0071\u0032\u004b\u005d\u0079\u006b\u007e\u0025\u0057\u004a\u0051\u003a\u0067\u0026\u0029\u004e\u0058\u0061\u004d\u006e\u004e\u0072\u005a\u003e\u0041\u0024\u007a\u003e\u0023\u005a\u0065\u0040\u0066\u0047\u0071\u0039\u0044\u0066\u0039\u002c\u0077\u0042\u0075\u005a\u0025\u005e\u007a\u0072\u0038\u003e\u0032\u0062\u0074\u0051\u0035\u0071\u0053\u0078\u0035\u0044\u005d\u0064\u0035\u0036\u0059\u0028\u0046\u0070\u0022\u003f\u0079\u007c\u0050\u005a\u007e\u0053\u0073\u0076\u0035\u0060\u003b\u0058\u0037\u0058\u0070\u0022\u002c\u0031\u0078\u004b\u0075\u0037\u0057\u0026\u004a\u0022\u005e\u0076\u005b\u0046\u0030\u0022\u0025\u0074\u004e\u0071\u0028\u0038\u0036\u004d\u0065\u0066\u0064\u0050\u005b\u004f\u006b\u0065\u0051\u0047\u0028\u0056\u0061\u0035\u0073\u004d\u0066\u002f\u0069\u0076\u002b\u005e\u0056\u0029\u0041\u005a\u0041\u0062\u0033\u006f\u0036\u006c\u004e\u0074\u007c\u005d\u002b\u0042\u0036\u004f\u0029\u0078\u004e\u0076\u0074\u007a\u007b\u0041\u003d\u0033\u0029\u0059\u006c\u004e\u0028\u004b\u0079\u002a\u0041\u0056\u0072\u0066\u0067\u0078\u004e\u0048\u0041\u006f\u006a\u003e\u0035\u0070\u0056\u005e\u006b\u0031\u003f\u0044\u0023\u0031\u0060\u0062\u007d\u0075\u007a\u0029\u0072\u0042\u007b\u0078\u0071\u0063\u0073\u0032\u005a\u006e\u0048\u0064\u007d\u0033\u0045\u005a\u007e\u003b\u002f\u0040\u0038\u0078\u003c\u0029\u004c\u002e\u006c\u0040\u0079\u0037\u003c\u0037\u002f\u0073\u006a\u0064\u002b\u0034\u0057\u004d\u0041\u007c\u0056\u0070\u004e\u0048\u0078\u0069\u002f\u0062\u0053\u0073\u003f\u006c\u007d\u007b\u007c\u007e\u0031\u0024\u004b\u0077\u0032\u0030\u0066\u0039\u0054\u0039\u004e\u002b\u0056\u0050\u0076\u0079\u0042\u003f\u0044\u0051\u0025\u005e\u007e\u0063\u0029\u002c\u0059\u004f\u0054\u0064\u0028\u0053\u0043\u0048\u006b\u0075\u0042\u003a\u0064\u0022\u0036\u0068\u0053\u0059\u0052\u0071\u004c\u0061\u0026\u0078\u003f\u003b\u002c\u0058\u004f\u0036\u005a\u0028\u0053\u0041\u0025\u002e\u0069\u0021\u0072\u002c\u006c\u005e\u0056\u0024\u0068\u0053\u007e\u0031\u0050\u0029\u004a\u007d\u007a\u0071\u002e\u0047\u0064\u0070\u006a\u007c\u003c\u006e\u0071\u0079\u0043\u0075\u006f\u0033\u007a\u0037\u0071\u0048\u004d\u0070\u0047\u004a\u007c\u0068\u0030\u006d\u0070\u0021\u0049\u0078\u0036\u0040\u0046\u002b\u0021\u0031\u0024\u0046\u0072\u006c\u0061\u005b\u004a\u004d\u0026\u006c\u0036\u0028\u004a\u0023\u0021\u005f\u005a\u0037\u006d\u0076\u004f\u0071\u0038\u0078\u007a\u0068\u004b\u0026\u0075\u0076\u0046\u0065\u0076\u005d\u005f\u004b\u007b\u0043\u0062\u0073\u005f\u0076\u006e\u0068\u0034\u004e\u0060\u003a\u006e\u002a\u0067\u0042\u0072\u0075\u006c\u0049\u007a\u002a\u0054\u006f\u0040\u006a\u0051\u0046\u0040\u0038\u0036\u0029\u004b\u0022\u006f\u002e\u0064\u004f\u0026\u0041\u0049\u0034\u007d\u0059\u0034\u006d\u002f\u0079\u0025\u0038\u0035\u006c\u0049\u006d\u007d\u003f\u0053\u0050\u0033\u004d\u0058\u004d\u004e\u004e\u003d\u006b\u0035\u0036\u0071\u005f\u003e\u004e\u006d\u0052\u0072\u003d\u003a\u0062\u0073\u005f\u0076\u006e\u0068\u0043\u0040\u0022\u0053\u0047\u007e\u0043\u0051\u0049\u0071\u0071\u0049\u004c\u005b\u0046\u003b\u0032\u0039\u0043\u0078\u0064\u007b\u0075\u0028\u002b\u0038\u003f\u005f\u0066\u006a\u0049\u0062\u0054\u004b\u0039\u0058\u007d\u002e\u006d\u002b\u0069\u0066\u003f\u0026\u002c\u002c\u0026\u0077\u003d\u003a\u0023\u0040\u0061\u006a\u0041\u0078\u0031\u0025\u0048\u0063\u0055\u0037\u004b\u004a\u005a\u0059\u0045\u003d\u0038\u0054\u0052\u007b\u0056\u0047\u004a\u0065\u0067\u004e\u0023\u0055\u005f\u006e\u0079\u0034\u0077\u0070\u005e\u002a\u004c\u0061\u007c\u0079\u0068\u0056\u0035\u0078\u0034\u007c\u0030\u002a\u004b\u0075\u0040\u0043\u0079\u003a\u007a\u0030\u0055\u007d\u003b\u0030\u0074\u002b\u0076\u0035\u0036\u0043\u004c\u0060\u005b\u0022\u005e\u006b\u004d\u0035\u0070\u0070\u003c\u0073\u0074\u0055\u0064\u0023\u007c\u0064\u0079\u0040\u0038\u0053\u0046\u0050\u0076\u003b\u0060\u0032\u002b\u0049\u0067\u0066\u0033\u0032\u0079\u0067\u0037\u0063\u0067\u0070\u004a\u0060\u0023\u0047\u0072\u0053\u0023\u0042\u0059\u003c\u0030\u0030\u0034\u0058\u0033\u0075\u0036\u0031\u006a\u0074\u003f\u0060\u002b\u006a\u0044\u0054\u0021\u0037\u0028\u0073\u002b\u002c\u0021\u0039\u0031\u0040\u006f\u004b\u003b\u002c\u0023\u003b\u0072\u002e\u006f\u004a\u005d\u004d\u0038\u0038\u004d\u0050\u0044\u0065\u003c\u004a\u0026\u003e\u0074\u0034\u0076\u007a\u0073\u0025\u002e\u002b\u0031\u0041\u0022\u006d\u0038\u0021\u0052\u0025\u003e\u0035\u0076\u003b\u0079\u0022\u0038\u0041\u004e\u0024\u0026\u0073\u0032\u0033\u007e\u0047\u0071\u0063\u0057\u0025\u0036\u0060\u0073\u006d\u0070\u005d\u0050\u004b\u0028\u007b\u006b\u005d\u0021\u004d\u004e\u0075\u0075\u004e\u0077\u005f\u0075\u0021\u0035\u0021\u002e\u003d\u004e\u0050\u0040\u0042\u0021\u0057\u004d\u003a\u0058\u0055\u0048\u0053\u0051\u005a\u0074\u002c\u002e\u002e\u003c\u0061\u0040\u005a\u0075\u0021\u0042\u003e\u0078\u0041\u0079\u005e\u005d\u0061\u0030\u003c\u0074\u005a\u0044\u0031\u0073\u0035\u0060\u0033\u0038\u0066\u0031\u005e\u002e\u0061\u0065\u0050\u0066\u004d\u002b\u0039\u006c\u0022\u0034\u007b\u003d\u0051\u0065\u0055\u002e\u0061\u003a\u0033\u0025\u0025\u0060\u0063\u006f\u0068\u004f\u007d\u003e\u0034\u006d\u002a\u003b\u0042\u0068\u007d\u0047\u0068\u0060\u005f\u0066\u0076\u0069\u0078\u0034\u0032\u0028\u004c\u003b\u003f\u0026\u0036\u002c\u005a\u0072\u0060\u0045\u005b\u0048\u0021\u006f\u002e\u007c\u0067\u0058\u003b\u0054\u0070\u0073\u0038\u0024\u0036\u0024\u003a\u003b\u0044\u004f\u007b\u002c\u0066\u006c\u007e\u0054\u0043\u0039\u0050\u0022\u0067\u0078\u0028\u007c\u0073\u0034\u0070\u003b\u0071\u0064\u0045\u003d\u0025\u0036\u0023\u0079\u0060\u006f\u0037\u0052\u0021\u0057\u0072\u0037\u0043\u007a\u006e\u0033\u007a\u003f\u0068\u0053\u0042\u0054\u004c\u0071\u004b\u0076\u0034\u0050\u007e\u004c\u0066\u004b\u0021\u0047\u005a\u0075\u0024\u0042\u0061\u0076\u0052\u004d\u0050\u0040\u0063\u0046\u0051\u002f\u0054\u003f\u0032\u0040\u006c\u0061\u0053\u0067\u003e\u0036\u004e\u0073\u0048\u0032\u0036\u004a\u003a\u002a\u007c\u002c\u003f\u006d\u006b\u004d\u002e\u003d\u0061\u0067\u003c\u005e\u005a\u007c\u0067\u0041\u0028\u0042\u0068\u0048\u002a\u0033\u004a\u0060\u005a\u0038\u004a\u007e\u003f\u0021\u004b\u0052\u004e\u002a\u003f\u0036\u006b\u0042\u0076\u0055\u0058\u004f\u0067\u0064\u0037\u0054\u0029\u004a\u0066\u0032\u004f\u005e\u0028\u0048\u002c\u002e\u004d\u0068\u007b\u006e\u0061\u003a\u0075\u0049\u003f\u004d\u0044\u0047\u0079\u007a\u0063\u004c\u005a\u004f\u004d\u004c\u004c\u0047\u007a\u0051\u0053\u005a\u007c\u0077\u004e\u006a\u0051\u0031\u0051\u0030\u0022\u0060\u0055\u005d\u0024\u006d\u0075\u0071\u002a\u007e\u0071\u0064\u003f\u003f\u0034\u0079\u0044\u0022\u0022\u0026\u006a\u006d\u0033\u006f\u0054\u0069\u0075\u0042\u0056\u0035\u0063\u0031\u0044\u002f\u0048\u002e\u0029\u0046\u0061\u0053\u004d\u006e\u0072\u006d\u0053\u002e\u0079\u0073\u0070\u0052\u0031\u004e\u003d\u006e\u006e\u0045\u006d\u006f\u0056\u0051\u004c\u0077\u0031\u0031\u0062\u0054\u0030\u007d\u0054\u002e\u0022\u0066\u0049\u004d\u0076\u0039\u006e\u0058\u0057\u0043\u0057\u002c\u0043\u006e\u007d\u006c\u0065\u0055\u0022\u0073\u0071\u002a\u0031\u0053\u0059\u0058\u003b\u0042\u0042\u0049\u005f\u007d\u003f\u002b\u0047\u0032\u0043\u006e\u007d\u006c\u0065\u0055\u0026\u0062\u0028\u007e\u0046\u0071\u0058\u007d\u002e\u0056\u0023\u0046\u0052\u0024\u0032\u0022\u0021\u0070\u0072\u004b\u006d\u0058\u002c\u0059\u0073\u007d\u002e\u0036\u0047\u0068\u0049\u0064\u007b\u0033\u0062\u0024\u002a\u002a\u006c\u0052\u0059\u0072\u0050\u0045\u005e\u005b\u0026\u0057\u0074\u005e\u004c\u0077\u005a\u0047\u003f\u005a\u006d\u005e\u0034\u0040\u006a\u0072\u0029\u0074\u005e\u004c\u0077\u005a\u0047\u0067\u0073\u002c\u0044\u006e\u0067\u0040\u0049\u0049\u0053